        // This code is vulnerable to path traversal attacks because it directly concatenates user input
        // into the file path without validation, allowing an attacker to access files outside the intended directory.
        String userInput = args[0]; 
        File unsafeFile = new File("/safe/directory/" + userInput); 

        if (unsafeFile.exists()) {
            System.out.println("Reading file: " + unsafeFile.getAbsolutePath());
