import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileAccess {
    public static void main(String[] args) {
        String userInput = args[0];

        // Construct the base safe directory and the target path separately
        Path basePath = Paths.get("/safe/directory");
        Path targetPath = basePath.resolve(userInput).normalize();

        // Verify that the resolved path still starts with the base directory
        // This prevents attackers from using "../" sequences to escape the allowed folder
        if (!targetPath.startsWith(basePath)) {
            throw new SecurityException("Access denied: Attempted path traversal detected.");
        }

        File safeFile = targetPath.toFile();

        if (safeFile.exists()) {
            System.out.println("Reading secure file: " + safeFile.getAbsolutePath());
        }
    }
}
